interface CartElement extends HTMLElement {
  changeItemQuantity: (itemId: string | number, quantity: number) => void;
}

class UwpMiniCartBody extends HTMLElement {
  connectedCallback() {
    this.addEventListener("click", this.#onClick);
  }

  disconnectedCallback() {
    this.removeEventListener("click", this.#onClick);
  }

  #onClick = (event: Event) => {
    const target = event.target as HTMLElement;
    if (
      !target.classList.contains("minicart__item__increment") &&
      !target.classList.contains("minicart__item__decrement")
    ) {
      return;
    }

    const input = target.parentElement?.querySelector<HTMLInputElement>(
      ".minicart__item__quantity",
    );
    if (!input) return;

    const current = parseInt(input.value, 10) || 1;
    const max = parseInt(input.getAttribute("max") || "9999", 10);
    let next =
      current +
      (target.classList.contains("minicart__item__increment") ? 1 : -1);
    if (next < 1) next = 1;
    if (next > max) next = max;

    if (next === current) return;

    const variantId = input.dataset.id;
    if (!variantId) return;

    (document.querySelector("uwp-cart") as CartElement)?.changeItemQuantity(
      variantId,
      next,
    );
  };
}

customElements.define("uwp-minicart-body", UwpMiniCartBody);